// Initialize quarterly reporting process
const now = new Date();

// Calculate quarter information
const currentQuarter = Math.floor((now.getMonth() + 3) / 3);
const currentYear = now.getFullYear();

// Calculate previous quarter (the one we're reporting on)
let reportingQuarter, reportingYear;
if (currentQuarter === 1) {
  reportingQuarter = 4;
  reportingYear = currentYear - 1;
} else {
  reportingQuarter = currentQuarter - 1;
  reportingYear = currentYear;
}

// Format quarter string
const quarterString = `Q${reportingQuarter} ${reportingYear}`;

// Calculate quarter date ranges
const quarterStartMonth = (reportingQuarter - 1) * 3;
const quarterStartDate = new Date(reportingYear, quarterStartMonth, 1);
const quarterEndDate = new Date(reportingYear, quarterStartMonth + 3, 0);

// Format date strings
const quarterStartString = quarterStartDate.toISOString().split('T')[0];
const quarterEndString = quarterEndDate.toISOString().split('T')[0];

// Create reporting object
const reportingData = {
  reportId: `QR-${reportingYear}-${reportingQuarter}`,
  quarterString,
  reportingQuarter,
  reportingYear,
  quarterStartDate: quarterStartString,
  quarterEndDate: quarterEndString,
  generationDate: now.toISOString(),
  status: 'Initiated',
  distributionStatus: 'Pending',
  reportingDeadline: new Date(now.getFullYear(), now.getMonth(), now.getDate() + 30).toISOString()
};

return { json: reportingData };

// Combine all data for quarterly report generation
const reportingData = $input.first().json;
const limitedPartners = $input.all()[1].json;
const portfolioCompanies = $input.all()[2].json;
const fundPerformance = $input.all()[3].json;

// Filter portfolio companies for active investments
const activeCompanies = portfolioCompanies.filter(company => company.status === 'Active');

// Filter fund performance for the reporting quarter
const quarterPerformance = fundPerformance.find(perf => 
  perf.quarter === reportingData.reportingQuarter && 
  perf.year === reportingData.reportingYear
) || {};

// Calculate fund metrics
const totalInvested = activeCompanies.reduce((sum, company) => sum + parseFloat(company.investmentAmount || 0), 0);
const totalValuation = activeCompanies.reduce((sum, company) => sum + parseFloat(company.currentValuation || 0), 0);
const totalMultiple = totalInvested > 0 ? totalValuation / totalInvested : 1;

// Prepare report data
const reportData = {
  ...reportingData,
  fundName: 'VC Fund I',
  fundManager: 'VC Firm Management',
  lpCount: limitedPartners.length,
  portfolioCount: activeCompanies.length,
  totalCommitted: quarterPerformance.totalCommitted || 0,
  totalCalled: quarterPerformance.totalCalled || 0,
  totalDistributed: quarterPerformance.totalDistributed || 0,
  totalInvested,
  totalValuation,
  netIRR: quarterPerformance.netIRR || 0,
  grossIRR: quarterPerformance.grossIRR || 0,
  tvpi: quarterPerformance.tvpi || totalMultiple,
  dpi: quarterPerformance.dpi || 0,
  rvpi: quarterPerformance.rvpi || totalMultiple,
  moic: quarterPerformance.moic || totalMultiple,
  newInvestments: quarterPerformance.newInvestments || [],
  exitedInvestments: quarterPerformance.exitedInvestments || [],
  followOnInvestments: quarterPerformance.followOnInvestments || [],
  keyUpdates: quarterPerformance.keyUpdates || ''
};

// Add LP data for individual reports
reportData.limitedPartners = limitedPartners.map(lp => ({
  ...lp,
  reportId: reportingData.reportId,
  quarterString: reportingData.quarterString,
  reportStatus: 'Pending'
}));

return { json: reportData };

