// Generate individual LP reports
const reportData = $input.first().json;
const folderId = $input.all()[1].json.id;

// Create an array of items for each LP
const lpReports = reportData.limitedPartners.map(lp => {
  // Calculate LP-specific metrics
  const lpCommitment = parseFloat(lp.commitment || 0);
  const lpPercentage = reportData.totalCommitted > 0 ? lpCommitment / reportData.totalCommitted : 0;
  const lpCalled = reportData.totalCalled * lpPercentage;
  const lpDistributed = reportData.totalDistributed * lpPercentage;
  const lpNav = (reportData.totalValuation * lpPercentage) - lpDistributed;

  return {
    json: {
      ...reportData,
      ...lp,
      folderId,
      lpCommitment,
      lpPercentage,
      lpCalled,
      lpDistributed,
      lpNav,
      lpTvpi: lpCalled > 0 ? (lpNav + lpDistributed) / lpCalled : 0,
      lpDpi: lpCalled > 0 ? lpDistributed / lpCalled : 0,
      lpRvpi: lpCalled > 0 ? lpNav / lpCalled : 0,
      reportFilename: `${reportData.fundName} - ${reportData.quarterString} - ${lp.name}.pdf`
    }
  };
});

return lpReports;

// Check if reports are ready for distribution
const pendingReport = $input.item.json;

// If no pending reports, return empty
if (!pendingReport) {
  return { json: { readyForDistribution: false } };
}

// Check if generation date is at least 2 days ago (giving time for review)
const generationDate = new Date(pendingReport.generationDate);
const now = new Date();
const daysSinceGeneration = Math.floor((now - generationDate) / (24 * 60 * 60 * 1000));

// Reports are ready for distribution if they were generated at least 2 days ago
const readyForDistribution = daysSinceGeneration >= 2;

return {
  json: {
    ...pendingReport,
    readyForDistribution,
    daysSinceGeneration
  }
};

