// Initialize tax document distribution process
const now = new Date();

// Calculate tax year (previous year)
const taxYear = now.getFullYear() - 1;

// Create tax distribution object
const taxData = {
  distributionId: `TAX-${taxYear}`,
  taxYear,
  generationDate: now.toISOString(),
  status: 'Initiated',
  distributionStatus: 'Pending',
  distributionDeadline: new Date(now.getFullYear(), 2, 15).toISOString() // March 15 deadline
};

return { json: taxData };

// Generate individual LP tax documents
const taxData = $input.first().json;
const limitedPartners = $input.all()[1].json;
const folderId = $input.all()[2].json.id;

// Create an array of items for each LP
const lpTaxDocs = limitedPartners.map(lp => {
  return {
    json: {
      ...taxData,
      ...lp,
      folderId,
      documentType: lp.entityType === 'Individual' ? 'Schedule K-1' : 'Partnership Tax Return',
      documentFilename: `${taxData.taxYear} - ${lp.name} - ${lp.entityType === 'Individual' ? 'K1' : 'Tax Return'}.pdf`
    }
  };
});

return lpTaxDocs;

